import {shoppingList,monday,shiftWeek,normalize,dateKey} from './logic.js';
import {seed,photos} from './seed.js';
import {KitchenSync,emptyKitchen} from './sync.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'▦',pantry:'▤',planner:'▦',recipes:'▧',shopping:'♧',calendar:'▦'};
const units=['each','g','kg','oz','lb','ml','l','tsp','tbsp','cup'],categories=['Produce','Grains','Dairy & eggs','Protein','Canned goods','Staples','Bakery','Frozen','Other'];
const uid=()=>crypto.randomUUID(),fmt=n=>Number(n.toFixed(2)).toString();
let state;try{state=JSON.parse(localStorage.getItem('pantry-table-v1'))||seed();if(state.version!==1||!Array.isArray(state.pantry)||!Array.isArray(state.recipes)||!Array.isArray(state.plan))state=seed();}catch{state=seed();}
state.history ||= [];
try {validateBackup(state);const safeId=/^[a-zA-Z0-9_-]+$/;if([...state.pantry,...state.recipes,...state.plan,...state.custom,...state.history].some(x=>!safeId.test(x.id)))throw Error();} catch {state=seed();state.history=[];}
let view='home',week=monday(),search='',filter='All',audit=false,calendarMonth=monday().slice(0,7);
let cloud;
function save(){if(cloud?.user){cloud.setLocal(state);return;}try{localStorage.setItem('pantry-table-v1',JSON.stringify(state));}catch{toast('Your browser could not save changes. Export a backup from Settings.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3600);}
const needs=()=>shoppingList(state.pantry,state.recipes,state.plan,week);
const date=d=>new Date(d+'T12:00:00');
function weekLabel(){const start=date(week),end=date(week);end.setDate(end.getDate()+6);return start.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' – '+end.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}
function goto(next){view=next;search='';filter='All';audit=false;render();window.scrollTo(0,0);}
function badge(r){const missing=shoppingList(state.pantry,[r],[{week,recipeId:r.id,servings:r.servings}],week).length;return `<span class="availability ${missing?'':'ready'}">${missing?`${missing} ingredient${missing>1?'s':''} to shop`:'Everything in your pantry'}</span>`;}
function recipeCard(r){return `<article class="recipe-card"><button class="image-button" data-recipe="${r.id}" aria-label="View ${esc(r.name)}"><img src="${esc(r.image||photos.salad)}" alt="" loading="lazy"><span class="photo-tag">${esc(r.category)}</span></button><div class="recipe-body"><div class="meta">◷ ${r.minutes} min <span>·</span> ${r.servings} servings</div><button class="text-button recipe-title" data-recipe="${r.id}">${esc(r.name)}</button>${badge(r)}<button class="recipe-plan" data-plan="${r.id}">＋ Add to plan</button></div></article>`;}
function render(){const missing=needs().length;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-nav="home"><img src="/icon.svg" alt=""><span>pantry<span class="amp"> & </span>table<small>A LITTLE MORE HOMEMADE</small></span></a><nav>${[['home','Overview'],['pantry','My pantry'],['planner','Meal planner'],['calendar','Calendar'],['recipes','Recipes'],['shopping','Shopping list']].map(([id,label])=>`<button class="nav-item ${view===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icons[id]}</span>${label}${id==='shopping'&&missing?`<span class="count">${missing}</span>`:''}</button>`).join('')}</nav><div class="sidebar-tip"><span class="sprout">♧</span><strong>Good food starts here.</strong><p>Use what you have.<br>Plan what you love.<br>Waste a little less.</p></div><button class="profile" id="settings"><span class="avatar">Y</span><span>Your kitchen<small id="profile-status">${esc(syncLabel())}</small></span><span>⚙</span></button></aside><div class="workspace"><header class="topbar"><div><span class="breadcrumb">Your kitchen</span><span class="divider">/</span>${{home:'Overview',pantry:'My pantry',planner:'Meal planner',recipes:'Recipes',shopping:'Shopping list',calendar:'Calendar'}[view]}</div><div class="sync-controls" id="sync-controls">${authControls()}</div></header><main><div id="sync-notice">${syncNotice()}</div>${view==='home'?home():view==='pantry'?pantry():view==='planner'?planner():view==='recipes'?recipes():view==='calendar'?calendar():shopping()}</main><footer>Made for real life. And really good food.<span>Pantry & Table · Your kitchen, connected</span></footer></div>`;bind();}
function title(kicker,heading,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${heading}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function demoBanner(){return state.demo?`<div class="demo-banner"><span><strong>A taste of what’s possible.</strong> You’re exploring a sample kitchen. Make it yours whenever you’re ready.</span><button id="clear-demo">Start my kitchen</button></div>`:'';}
function home(){const planned=state.plan.filter(m=>m.week===week);return `${title('YOUR KITCHEN, CONNECTED','A good week starts here.','A little less “what’s for dinner?” A little more looking forward to it.',`<button class="button primary" data-nav="planner">＋ Plan a meal</button>`)}${demoBanner()}<section class="hero"><div class="hero-copy"><div class="eyebrow">FROM PANTRY TO PLATE</div><h2>Less guesswork.<br>More good food.</h2><p>Bring your pantry, recipes, and plans together.<br>We’ll take care of the shopping list.</p><button class="button light" data-nav="planner">Plan your week</button><div class="hero-foot">A plan that starts with what you already have.</div></div><div class="hero-image"><img src="${photos.salad}" alt="A colorful bowl of fresh vegetables"><span class="hero-label">A fresh start for your kitchen <span>✳</span></span></div></section><section class="stats"><button data-nav="pantry"><span class="stat-icon">▤</span><div><strong>${state.pantry.length}</strong><span>items in your pantry</span></div><span class="stat-link">View pantry</span></button><button data-nav="planner"><span class="stat-icon peach">▦</span><div><strong>${planned.length}</strong><span>meals planned this week</span></div><span class="stat-link">View plan</span></button><button data-nav="shopping"><span class="stat-icon yellow">♧</span><div><strong>${needs().length}</strong><span>ingredients to pick up</span></div><span class="stat-link">View list</span></button></section><section class="section"><div class="section-heading"><div><h2>On the menu this week</h2><p>${weekLabel()} <span class="tiny-pill">${planned.length} meals planned</span></p></div><button class="text-button" data-nav="planner">Open meal planner</button></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const day=date(week);day.setDate(day.getDate()+i);const meals=planned.filter(m=>m.day===i);return `<button class="day-preview ${dateKey(day)===dateKey(new Date())?'today':''}" data-day="${i}"><div>${day.toLocaleDateString('en-US',{weekday:'short'})}<span>${day.getDate()}</span></div>${meals.length?meals.map(m=>{const r=state.recipes.find(r=>r.id===m.recipeId);return r?`<img src="${esc(r.image||photos.salad)}" alt=""><small>${esc(r.name)}</small>`:'';}).join(''):'<span class="day-add">＋</span><small class="muted">Something delicious?</small>'}</button>`;}).join('')}</div></section><section class="section"><div class="section-heading"><div><div class="eyebrow">A LITTLE INSPIRATION</div><h2>Good food, within reach</h2><p>Your recipes, ready for the week ahead.</p></div><button class="text-button" data-nav="recipes">Browse recipes</button></div><div class="recipe-grid">${state.recipes.slice(0,3).map(recipeCard).join('')||empty('Your recipe book starts here.','Add a recipe','recipes')}</div></section>`;}
function empty(text,label,nav){return `<div class="empty"><span>♧</span><h3>${text}</h3>${nav?`<button class="button" data-nav="${nav}">${label}</button>`:''}</div>`;}
function pantry(){const items=state.pantry.filter(p=>(filter==='All'||p.location===filter)&&normalize(p.name).includes(normalize(search)));return `${title('KNOW WHAT YOU HAVE','My pantry','Your shelves, fridge, and freezer. All in one place.',`<button class="button" id="audit">${audit?'Finish audit':'☷ Audit pantry'}</button><button class="button primary" id="add-item">＋ Add item</button>`)}${audit?'<div class="notice">Audit mode: count what you have and update each quantity. Changes save as you go.</div>':''}<div class="toolbar"><div class="tabs">${['All','Pantry','Fridge','Freezer','Counter'].map(t=>`<button data-filter="${t}" class="${filter===t?'selected':''}">${t}</button>`).join('')}</div><input class="search" id="search" type="search" placeholder="Search your pantry…" value="${esc(search)}" aria-label="Search pantry"></div><div class="panel inventory"><div class="table-head"><span>Ingredient</span><span>On hand</span><span>Location</span><span>Best before</span><span></span></div>${items.map(p=>`<div class="inventory-row"><div class="ingredient-name"><span class="ingredient-icon">${{'Produce':'♧','Grains':'▧','Dairy & eggs':'◉','Staples':'◈'}[p.category]||'▤'}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small></span></div><div>${audit?`<input type="number" min="0" step="any" aria-label="Count ${esc(p.name)}" data-count="${p.id}" value="${p.quantity}">`:fmt(p.quantity)} <span class="muted">${esc(p.unit)}</span></div><span class="location">${esc(p.location)}</span><span class="${p.expiry&&p.expiry<dateKey(new Date())?'expired':'muted'}">${p.expiry?date(p.expiry).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Not set'}</span><button class="button small" data-edit-item="${p.id}">Edit</button></div>`).join('')||empty('No ingredients here yet.')}<div class="table-footer">${items.length} items <span>Keep quantities current for a more accurate shopping list.</span></div></div><p class="help-text">Ingredient names connect your pantry and recipes. Use the same name in both, such as “Cherry tomatoes”.</p>`;}
function weekControl(){return `<div class="week-control"><button id="prev-week" aria-label="Previous week">‹</button><span>${weekLabel()}</span><button id="next-week" aria-label="Next week">›</button><button id="this-week">Today</button></div>`;}
function planner(){return `${title('MAKE ROOM FOR GOOD FOOD','Your week, on a plate.','Plan the meals. We’ll find what’s missing from your pantry.',`<button class="button" data-nav="shopping">View shopping list</button><button class="button primary" id="add-meal">＋ Plan a meal</button>`)}<div class="toolbar">${weekControl()}<span class="muted">Plan for any day, any appetite.</span></div><div class="planner">${Array.from({length:7},(_,i)=>{const d=date(week);d.setDate(d.getDate()+i);return `<section class="plan-day"><div class="plan-date"><strong>${d.toLocaleDateString('en-US',{weekday:'long'})}</strong><span>${d.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div><div class="meal-slots">${['Breakfast','Lunch','Dinner'].map(slot=>{const m=state.plan.find(p=>p.week===week&&p.day===i&&p.slot===slot),r=m&&state.recipes.find(r=>r.id===m.recipeId);return `<div class="meal-slot"><span class="meal-label">${slot}</span>${r?`<div class="planned-meal"><button data-recipe="${r.id}" class="meal-detail"><img src="${esc(r.image||photos.salad)}" alt=""><span><strong>${esc(r.name)}</strong><small>${m.servings} servings · ${r.minutes} min</small></span></button><div class="meal-tools"><button data-cook-meal="${m.id}">${state.history.some(h=>h.mealId===m.id)?'Made ✓':'Mark made'}</button><button data-edit-meal="${m.id}" aria-label="Edit ${esc(r.name)}">Edit</button><button data-remove-meal="${m.id}" aria-label="Remove ${esc(r.name)}">×</button></div></div>`:`<button class="add-slot" data-slot="${i}|${slot}">＋ Plan ${slot.toLowerCase()}</button>`}</div>`;}).join('')}</div></section>`;}).join('')}</div>`;}
function recipes(){const visible=state.recipes.filter(r=>(filter==='All'||r.category===filter)&&normalize(r.name).includes(normalize(search)));return `${title('KEEP THE KEEPERS','Your recipe book.','Weeknight favorites, slow Sunday staples, and everything in between.',`<button class="button primary" id="add-recipe">＋ Add recipe</button>`)}<div class="toolbar"><div class="tabs">${['All',...new Set(state.recipes.map(r=>r.category))].map(t=>`<button data-filter="${esc(t)}" class="${filter===t?'selected':''}">${esc(t)}</button>`).join('')}</div><input class="search" id="search" type="search" placeholder="Find a recipe…" value="${esc(search)}" aria-label="Search recipes"></div><div class="recipe-grid library">${visible.map(recipeCard).join('')||empty('No recipes found.')}</div>`;}
function shopping(){const list=needs(),custom=state.custom.filter(c=>c.week===week),all=[...list,...custom];return `${title('JUST WHAT YOU NEED','A smarter shopping list.','Your planned meals, minus what’s already in your pantry.',`<button class="button" id="add-grocery">＋ Add extra</button><button class="button primary" id="purchase">Put checked items away</button>`)}<div class="toolbar">${weekControl()}<button class="text-button" id="print">Print list</button></div><div class="shopping-layout"><div class="panel grocery-list"><div class="list-heading"><h2>The essentials</h2><span>${all.length} items · ${all.filter(n=>state.checked.includes(week+'|'+n.key)).length} checked</span></div>${all.map(n=>`<label class="grocery-item ${state.checked.includes(week+'|'+n.key)?'checked':''}"><input type="checkbox" data-check="${esc(n.key)}" ${state.checked.includes(week+'|'+n.key)?'checked':''}><span><strong>${esc(n.name)}</strong><small>${n.recipes?esc(n.recipes.join(' · ')):'Extra for your kitchen'}</small></span><strong>${fmt(n.quantity)} <span class="muted">${esc(n.unit)}</span></strong>${n.manual?`<button class="remove-extra" data-remove-extra="${n.id}" aria-label="Remove ${esc(n.name)}">×</button>`:''}</label>`).join('')||empty('You’re all stocked up.','Plan another meal','planner')}</div><aside class="shopping-note"><div class="eyebrow">A LIST THAT KEEPS UP</div><h2>From your plan.<br>For your pantry.</h2><p>Ingredients are combined across every meal this week, then compared with what you have.</p><hr><p>Check items as you shop. When you put them away, we’ll add those quantities to your pantry.</p><small>Different measurement types stay separate. For example, grams and cups need their own entries.</small></aside></div>`;}
function bind(){
bindSyncControls();
document.querySelectorAll('[data-edit-history]').forEach(b=>b.onclick=()=>{const h=state.history.find(h=>h.id===b.dataset.editHistory);cookForm(h.recipeId,null,h.date,h);});
document.querySelectorAll('[data-cook-meal]').forEach(e=>e.onclick=()=>{const m=state.plan.find(p=>p.id===e.dataset.cookMeal);cookForm(m.recipeId,m);});
on('previous-month',()=>changeMonth(-1));on('following-month',()=>changeMonth(1));on('current-month',()=>{calendarMonth=dateKey(new Date()).slice(0,7);render();});on('log-cooking',()=>cookForm());
document.querySelectorAll('[data-calendar-day]').forEach(e=>e.onclick=()=>dayDetails(e.dataset.calendarDay));
document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=ev=>{ev.preventDefault();goto(e.dataset.nav);});document.querySelectorAll('[data-recipe]').forEach(e=>e.onclick=()=>showRecipe(e.dataset.recipe));document.querySelectorAll('[data-plan]').forEach(e=>e.onclick=()=>mealForm({recipeId:e.dataset.plan}));document.querySelectorAll('[data-day]').forEach(e=>e.onclick=()=>mealForm({day:Number(e.dataset.day)}));document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{filter=e.dataset.filter;render();});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});on('add-item',()=>itemForm());document.querySelectorAll('[data-edit-item]').forEach(e=>e.onclick=()=>itemForm(state.pantry.find(p=>p.id===e.dataset.editItem)));on('audit',()=>{audit=!audit;render();});document.querySelectorAll('[data-count]').forEach(e=>e.onchange=()=>{if(!e.validity.valid||e.value==='')return;state.pantry.find(p=>p.id===e.dataset.count).quantity=Number(e.value);save();});on('add-recipe',()=>recipeForm());on('add-meal',()=>mealForm());document.querySelectorAll('[data-slot]').forEach(e=>e.onclick=()=>{const [day,slot]=e.dataset.slot.split('|');mealForm({day:Number(day),slot});});document.querySelectorAll('[data-edit-meal]').forEach(e=>e.onclick=()=>mealForm(state.plan.find(m=>m.id===e.dataset.editMeal)));document.querySelectorAll('[data-remove-meal]').forEach(e=>e.onclick=()=>{state.plan=state.plan.filter(m=>m.id!==e.dataset.removeMeal);save();render();toast('Meal removed. Shopping list updated.');});on('prev-week',()=>{week=shiftWeek(week,-1);render();});on('next-week',()=>{week=shiftWeek(week,1);render();});on('this-week',()=>{week=monday();render();});document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{const k=week+'|'+e.dataset.check;state.checked=state.checked.filter(x=>x!==k);if(e.checked)state.checked.push(k);save();render();});on('purchase',purchase);on('add-grocery',groceryForm);document.querySelectorAll('[data-remove-extra]').forEach(e=>e.onclick=ev=>{ev.preventDefault();state.custom=state.custom.filter(c=>c.id!==e.dataset.removeExtra);save();render();});on('print',()=>window.print());on('settings',settings);on('clear-demo',()=>confirmAction('Start your own kitchen?','This clears the sample pantry, recipes, and meal plans. Add your own ingredients and favorites next.',()=>{state={version:1,pantry:[],recipes:[],plan:[],checked:[],custom:[],history:[],demo:false};save();goto('pantry');toast('Your kitchen is ready. Add your first ingredient.');}));}
function on(id,fn){const e=document.getElementById(id);if(e)e.onclick=fn;}
function modal(title,body){const d=$('#modal');d.innerHTML=`<div class="modal-top"><h2>${title}</h2><button id="close-modal" aria-label="Close dialog">×</button></div>${body}`;on('close-modal',()=>d.close());if(!d.open)d.showModal();}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');}
function field(label,input){return `<label class="field"><span>${label}</span>${input}</label>`;}
function actions(label,deleteId=''){return `<div class="form-actions">${deleteId?`<button type="button" class="text-button danger" id="${deleteId}">Delete</button>`:''}<button type="submit" class="button primary">${label}</button></div>`;}
function confirmAction(title,body,fn){modal(title,`<p>${body}</p><div class="form-actions"><button class="button" id="cancel">Cancel</button><button class="button primary" id="confirm">Confirm</button></div>`);on('cancel',()=>$('#modal').close());on('confirm',()=>{$('#modal').close();fn();});}
function itemForm(item={}){modal(item.id?'Edit pantry item':'Add to your pantry',`<form id="item-form">${field('Ingredient name',`<input name="name" required maxlength="100" value="${esc(item.name||'')}" placeholder="e.g. Cherry tomatoes" list="ingredient-names">`)}<datalist id="ingredient-names">${[...new Set(state.recipes.flatMap(r=>r.ingredients.map(i=>i.name)))].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><div class="form-grid">${field('Quantity','<input name="quantity" required type="number" min="0" max="1000000" step="any" value="'+(item.quantity??1)+'">')}${field('Unit',`<select name="unit">${options(units,item.unit||'each')}</select>`)}${field('Category',`<select name="category">${options(categories,item.category||'Produce')}</select>`)}${field('Location',`<select name="location">${options(['Pantry','Fridge','Freezer','Counter'],item.location||'Pantry')}</select>`)}</div>${field('Best before (optional)',`<input name="expiry" type="date" value="${esc(item.expiry||'')}">`)}${actions('Save item',item.id?'delete-item':'')}</form>`);$('#item-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.name=f.name.trim();if(!f.name)return;f.quantity=Number(f.quantity);f.id=item.id||uid();state.pantry=state.pantry.filter(p=>p.id!==f.id);state.pantry.push(f);save();$('#modal').close();render();toast('Pantry saved. Shopping list updated.');};on('delete-item',()=>confirmAction('Delete this ingredient?',`Remove ${esc(item.name)} from your pantry?`,()=>{state.pantry=state.pantry.filter(p=>p.id!==item.id);save();render();}));}
function showRecipe(id){const r=state.recipes.find(r=>r.id===id);modal(esc(r.name),`<img class="recipe-modal-image" src="${esc(r.image||photos.salad)}" alt=""><div class="recipe-modal-meta">${esc(r.category)} · ${r.minutes} min · ${r.servings} servings</div><p>${esc(r.description)}</p><p class="last-made">${lastMade(r.id)}</p><h3>Ingredients</h3><ul class="ingredients">${r.ingredients.map(i=>`<li><span>${esc(i.name)}</span><strong>${fmt(i.quantity)} ${esc(i.unit)}</strong></li>`).join('')}</ul><h3>Let’s make it</h3><ol class="steps">${r.steps.split('\n').filter(Boolean).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="form-actions"><button class="button" id="log-recipe">Made this</button><button class="button" id="edit-recipe">Edit recipe</button><button class="button primary" id="plan-recipe">＋ Add to plan</button></div>`);on('log-recipe',()=>cookForm(r.id));on('edit-recipe',()=>recipeForm(r));on('plan-recipe',()=>mealForm({recipeId:r.id}));}
function ingredientRow(i={}){return `<div class="ingredient-edit"><input aria-label="Ingredient name" placeholder="Ingredient name" class="ing-name" value="${esc(i.name||'')}" required maxlength="100"><input aria-label="Ingredient quantity" class="ing-quantity" type="number" min="0.001" max="1000000" step="any" value="${i.quantity||1}" required><select aria-label="Ingredient unit" class="ing-unit">${options(units,i.unit||'each')}</select><button type="button" class="remove-ingredient" aria-label="Remove ingredient">×</button></div>`;}
function recipeForm(r={}){modal(r.id?'Edit recipe':'A new kitchen favorite',`<form id="recipe-form">${field('Recipe name',`<input name="name" required maxlength="100" value="${esc(r.name||'')}">`)}${field('A little about it',`<input name="description" maxlength="300" value="${esc(r.description||'')}">`)}<div class="form-grid">${field('Prep + cook time (minutes)',`<input name="minutes" type="number" min="1" max="1440" value="${r.minutes||30}" required>`)}${field('Servings',`<input name="servings" type="number" min="1" max="100" value="${r.servings||2}" required>`)}</div>${field('Category',`<select name="category">${options(['Vegetarian','Plant-based','Breakfast','Chicken','Seafood','Beef','Other'],r.category||'Other')}</select>`)}<h3>Ingredients</h3><p class="help-text">Match pantry names to let us find what you already have.</p><div id="ingredient-rows">${(r.ingredients||[{}]).map(ingredientRow).join('')}</div><button type="button" class="text-button" id="add-ingredient">＋ Another ingredient</button>${field('Instructions (one step per line)',`<textarea name="steps" rows="5" required>${esc(r.steps||'')}</textarea>`)}${actions('Save recipe',r.id?'delete-recipe':'')}</form>`);const wire=()=>document.querySelectorAll('.remove-ingredient').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.ingredient-edit').length>1)b.parentElement.remove();else toast('A recipe needs at least one ingredient.');});wire();on('add-ingredient',()=>{$('#ingredient-rows').insertAdjacentHTML('beforeend',ingredientRow());wire();});$('#recipe-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.name=f.name.trim();if(!f.name)return;f.ingredients=[...document.querySelectorAll('.ingredient-edit')].map(row=>({name:row.querySelector('.ing-name').value.trim(),quantity:Number(row.querySelector('.ing-quantity').value),unit:row.querySelector('.ing-unit').value}));if(f.ingredients.some(i=>!i.name))return;f.minutes=Number(f.minutes);f.servings=Number(f.servings);f.id=r.id||uid();f.image=r.image||photos.salad;state.recipes=state.recipes.filter(x=>x.id!==f.id);state.recipes.push(f);save();$('#modal').close();render();toast('Recipe saved to your book.');};on('delete-recipe',()=>confirmAction('Delete this recipe?','This also removes this recipe from all meal plans.',()=>{state.recipes=state.recipes.filter(x=>x.id!==r.id);state.plan=state.plan.filter(m=>m.recipeId!==r.id);save();render();}));}
function mealForm(m={}){if(!state.recipes.length){goto('recipes');recipeForm();toast('Add your first recipe, then plan a meal.');return;}modal(m.id?'Edit planned meal':'Something good on the menu',`<form id="meal-form"><p class="help-text">${weekLabel()}</p>${field('Recipe',`<select name="recipeId">${state.recipes.map(r=>`<option value="${r.id}" ${r.id===m.recipeId?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`)}<div class="form-grid">${field('Day',`<select name="day">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((d,i)=>`<option value="${i}" ${i===(m.day??0)?'selected':''}>${d}</option>`).join('')}</select>`)}${field('Meal',`<select name="slot">${options(['Breakfast','Lunch','Dinner'],m.slot||'Dinner')}</select>`)}</div>${field('How many servings?',`<input name="servings" type="number" min="1" max="100" value="${m.servings||state.recipes.find(r=>r.id===m.recipeId)?.servings||2}" required>`)}<p class="help-text">One recipe per meal slot. Saving replaces any meal already in that slot.</p>${actions('Save to meal plan')}</form>`);$('#meal-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.day=Number(f.day);f.servings=Number(f.servings);f.week=week;f.id=m.id||uid();state.plan=state.plan.filter(p=>p.id!==f.id&&!(p.week===week&&p.day===f.day&&p.slot===f.slot));state.plan.push(f);save();$('#modal').close();render();toast('Meal planned. Shopping list updated.');};}
function groceryForm(){modal('A little something extra',`<form id="extra-form">${field('Item',`<input name="name" required maxlength="100" placeholder="e.g. Coffee">`)}<div class="form-grid">${field('Quantity','<input name="quantity" type="number" min="0.001" max="1000000" step="any" value="1" required>')}${field('Unit',`<select name="unit">${options(units,'each')}</select>`)}</div>${actions('Add to list')}</form>`);$('#extra-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.name=f.name.trim();if(!f.name)return;f.id=uid();f.key='extra-'+f.id;f.manual=true;f.quantity=Number(f.quantity);f.week=week;state.custom.push(f);save();$('#modal').close();render();};}
function purchase(){const rows=[...needs(),...state.custom.filter(c=>c.week===week)].filter(n=>state.checked.includes(week+'|'+n.key));if(!rows.length){toast('Check the items you bought first.');return;}for(const n of rows){const found=state.pantry.find(p=>normalize(p.name)===normalize(n.name)&&p.unit===n.unit);if(found)found.quantity+=n.quantity;else state.pantry.push({id:uid(),name:n.name,quantity:n.quantity,unit:n.unit,category:'Other',location:'Pantry',expiry:''});state.custom=state.custom.filter(c=>c.key!==n.key);state.checked=state.checked.filter(k=>k!==week+'|'+n.key);}save();render();toast(`${rows.length} items added to your pantry.`);}
function settings(){
modal('Your kitchen, your data',`<p>${cloud?.user?'Signed in as '+esc(cloud.user.email)+'. Your kitchen syncs through your account.':'Explore on this device, or sign in to keep your kitchen in sync across devices.'}</p><div class="settings-actions">${cloud?.user?'<button class="button" id="account-signout">Sign out</button><button class="button" id="import-device">Import this device’s kitchen</button>':'<button class="button primary" id="account-signin">Sign in & sync</button>'}<button class="button" id="export">Download backup</button><button class="button" id="import">Restore backup</button><input id="import-file" type="file" accept="application/json" hidden></div><p class="help-text">Pantry stock changes when you edit it or put shopping away. Recording a cooked meal does not deduct ingredients.</p>`);
on('export',()=>downloadKitchen(state));on('account-signin',()=>authForm());on('account-signout',logout);
on('import-device',()=>{let saved;try{saved=JSON.parse(localStorage.getItem('pantry-table-v1'));validateBackup(saved);validateIds(saved);}catch{toast('There is no saved guest kitchen to import on this device.');return;}confirmAction('Import this device’s kitchen?','This replaces your account’s kitchen with the guest kitchen saved in this browser. Export your current kitchen first if you want to keep a backup.',()=>{state=saved;save();render();});});
on('import',()=>$('#import-file').click());$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(file.size>4000000)throw Error();const data=JSON.parse(await file.text());validateBackup(data);validateIds(data);confirmAction('Restore this backup?','This replaces the current kitchen, including its synced copy when signed in.',()=>{state=data;save();render();toast('Kitchen restored.');});}catch{toast('That backup is not a valid Pantry & Table file.');}};
}
function validateBackup(d){d.history ||= [];if(!Array.isArray(d.history)||d.history.some(h=>typeof h.id!=='string'||typeof h.recipeId!=='string'||typeof h.recipeName!=='string'||typeof h.notes!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!Number.isFinite(h.servings)||h.servings<=0))throw Error();if(d.version!==1||!['pantry','recipes','plan','checked','custom'].every(k=>Array.isArray(d[k])))throw Error();const s=x=>typeof x==='string',positive=n=>Number.isFinite(n)&&n>0;for(const p of d.pantry)if(!s(p.id)||!s(p.name)||!Number.isFinite(p.quantity)||p.quantity<0||!units.includes(p.unit)||!s(p.location)||!s(p.category)||!s(p.expiry))throw Error();for(const r of d.recipes)if(!s(r.id)||!s(r.name)||!s(r.steps)||!s(r.category)||!positive(r.servings)||!positive(r.minutes)||!Array.isArray(r.ingredients)||!r.ingredients.length||r.ingredients.some(i=>!s(i.name)||!positive(i.quantity)||!units.includes(i.unit))||r.image&&!/^https:\/\/images\.unsplash\.com\//.test(r.image))throw Error();for(const m of d.plan)if(!s(m.id)||!/^\d{4}-\d{2}-\d{2}$/.test(m.week)||!Number.isInteger(m.day)||m.day<0||m.day>6||!['Breakfast','Lunch','Dinner'].includes(m.slot)||!positive(m.servings)||!d.recipes.some(r=>r.id===m.recipeId))throw Error();for(const c of d.custom)if(!s(c.id)||!s(c.name)||!s(c.key)||!s(c.week)||!positive(c.quantity)||!units.includes(c.unit))throw Error();if(d.checked.some(k=>!s(k)))throw Error();}
cloud=new KitchenSync({
onState:data=>{try{validateBackup(data);validateIds(data);}catch{cloud.notify('invalid');return;}state=data;if(!$('#modal').open&&!audit)render();},
onStatus:()=>paintSyncUI(),
onUser:user=>{if(!user){try{state=JSON.parse(localStorage.getItem('pantry-table-v1'))||seed();validateBackup(state);validateIds(state);}catch{state=seed();state.history=[];}render();}},
});
render();cloud.start();
setInterval(()=>{if(document.visibilityState==='visible')cloud.sync();},15000);
window.addEventListener('online',()=>cloud.sync());
window.addEventListener('focus',()=>cloud.sync());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')cloud.sync();});
window.addEventListener('beforeunload',e=>{if(cloud.dirty||cloud.conflict){e.preventDefault();e.returnValue='';}});
$('#modal').addEventListener('close',()=>render());
if(new URL(location.href).searchParams.has('reset-password'))resetPasswordForm();
function lastMade(recipeId){const entries=state.history.filter(h=>h.recipeId===recipeId).sort((a,b)=>b.date.localeCompare(a.date));return entries.length?`Last made ${date(entries[0].date).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})} · Made ${entries.length} time${entries.length===1?'':'s'}`:'Not made yet. A new favorite waiting to happen.';}
function changeMonth(amount){const d=date(calendarMonth+'-01');d.setMonth(d.getMonth()+amount);calendarMonth=dateKey(d).slice(0,7);render();}
function plannedOn(day){return state.plan.filter(m=>{const d=date(m.week);d.setDate(d.getDate()+m.day);return dateKey(d)===day;});}
function calendar(){const first=date(calendarMonth+'-01'),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(start.getDate()-offset);const count=Math.ceil((offset+new Date(first.getFullYear(),first.getMonth()+1,0).getDate())/7)*7;const history=[...state.history].sort((a,b)=>b.date.localeCompare(a.date));return `${title('A RHYTHM FOR YOUR KITCHEN','Your kitchen calendar.','See what’s coming up, and remember the meals you made.',`<button class="button" data-nav="planner">Weekly planner</button><button class="button primary" id="log-cooking">＋ Log a meal made</button>`)}<div class="toolbar"><div class="week-control"><button id="previous-month" aria-label="Previous month">‹</button><strong>${first.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</strong><button id="following-month" aria-label="Next month">›</button><button id="current-month">This month</button></div><div class="calendar-legend"><span>◌ Planned</span><span>✓ Made</span></div></div><section class="panel month-calendar"><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=dateKey(d),planned=plannedOn(key),made=state.history.filter(h=>h.date===key);return `<button class="calendar-cell ${key.slice(0,7)!==calendarMonth?'other-month':''} ${key===dateKey(new Date())?'calendar-today':''}" data-calendar-day="${key}" aria-label="${d.toLocaleDateString('en-US',{month:'long',day:'numeric'})}, ${planned.length} planned, ${made.length} made"><span class="calendar-number">${d.getDate()}</span>${planned.map(m=>{const r=state.recipes.find(r=>r.id===m.recipeId);return r?`<span class="calendar-event"><span>◌ ${esc(m.slot)}</span>${esc(r.name)}</span>`:'';}).join('')}${made.map(h=>`<span class="calendar-event cooked"><span>✓ Made</span>${esc(h.recipeName)}</span>`).join('')}</button>`;}).join('')}</div></section><section class="section"><div class="section-heading"><div><h2>Around your table</h2><p>Your cooking history · ${history.length} meal${history.length===1?'':'s'} made</p></div></div><div class="panel history-list">${history.slice(0,30).map(h=>`<div class="history-row"><span class="history-check">✓</span><div><strong>${esc(h.recipeName)}</strong><small>${esc(h.notes||'A homemade moment.')} · ${h.servings} servings</small></div><span>${date(h.date).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><button class="button small" data-edit-history="${h.id}">Edit</button></div>`).join('')||empty('Your homemade memories start here.')}</div>${history.length>30?'<p class="help-text">Showing your 30 most recent meals. All entries remain visible on their calendar dates.</p>':''}</section>`;}
function dayDetails(day){const planned=plannedOn(day),made=state.history.filter(h=>h.date===day);modal(date(day).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}),`<h3>On the menu</h3>${planned.map(m=>{const r=state.recipes.find(r=>r.id===m.recipeId);return r?`<div class="day-meal"><span><strong>${esc(r.name)}</strong><small>${m.slot} · ${m.servings} servings</small></span><button class="button small" data-day-cook="${m.id}">Mark made</button></div>`:'';}).join('')||'<p>No meals planned for this day.</p>'}<h3>Made this day</h3>${made.map(h=>`<div class="day-meal"><span><strong>✓ ${esc(h.recipeName)}</strong><small>${esc(h.notes)} · ${h.servings} servings</small></span><button class="button small" data-day-history="${h.id}">Edit</button></div>`).join('')||'<p>No cooking recorded yet.</p>'}<div class="form-actions"><button class="button" id="plan-day">Plan a meal</button><button class="button primary" id="log-day">Log meal made</button></div>`);document.querySelectorAll('[data-day-cook]').forEach(b=>b.onclick=()=>{const m=state.plan.find(p=>p.id===b.dataset.dayCook);cookForm(m.recipeId,m,day);});document.querySelectorAll('[data-day-history]').forEach(b=>b.onclick=()=>{const h=state.history.find(h=>h.id===b.dataset.dayHistory);cookForm(h.recipeId,null,h.date,h);});on('plan-day',()=>{week=monday(date(day));mealForm({day:(date(day).getDay()+6)%7});});on('log-day',()=>cookForm(undefined,null,day));}
function cookForm(recipeId,meal=null,day=dateKey(new Date()),entry=null){if(!entry&&meal){entry=state.history.find(h=>h.mealId===meal.id);if(entry)day=entry.date;}if(!state.recipes.length&&!entry){goto('recipes');recipeForm();toast('Add a recipe to start your cooking history.');return;}modal(entry?'Edit meal made':'Another homemade moment',`<form id="cook-form">${field('Recipe',`<select name="recipeId">${entry&&!state.recipes.some(r=>r.id===entry.recipeId)?`<option value="${esc(entry.recipeId)}">${esc(entry.recipeName)} (archived)</option>`:''}${state.recipes.map(r=>`<option value="${r.id}" ${r.id===(entry?.recipeId||recipeId)?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`)}<div class="form-grid">${field('Date made',`<input name="date" type="date" required max="${dateKey(new Date())}" value="${entry?.date||day}">`)}${field('Servings made',`<input name="servings" type="number" min="1" max="100" required value="${entry?.servings||meal?.servings||state.recipes.find(r=>r.id===recipeId)?.servings||2}">`)}</div>${field('Kitchen notes (optional)',`<textarea name="notes" rows="3" maxlength="500" placeholder="A family favorite? Something to change next time?">${esc(entry?.notes||'')}</textarea>`)}<p class="help-text">This saves your cooking history. Update quantities in your pantry after cooking.</p>${actions('Save cooking record',entry?'delete-history':'')}</form>`);$('#cook-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),r=state.recipes.find(r=>r.id===f.recipeId);f.id=entry?.id||uid();f.recipeName=r?.name||entry.recipeName;f.servings=Number(f.servings);f.mealId=meal?.id||entry?.mealId||null;state.history=state.history.filter(h=>h.id!==f.id);state.history.push(f);save();$('#modal').close();render();toast('Meal recorded. A new memory around your table.');};on('delete-history',()=>confirmAction('Remove cooking record?','This removes this entry from your history. Your recipe and meal plan stay saved.',()=>{state.history=state.history.filter(h=>h.id!==entry.id);save();render();}));}
function validateIds(data){for(const group of ['pantry','recipes','plan','history','custom'])for(const row of data[group])if(!/^[a-zA-Z0-9_-]{1,100}$/.test(row.id))throw Error();}
function syncLabel(){if(!cloud)return 'Checking sync…';return {checking:'Checking sync…',setup:'Saved on this device',guest:'Saved on this device',loading:'Loading your kitchen…',syncing:'Syncing…',synced:'Up to date',pending:'Changes waiting to sync',offline:'Offline · saved here',unavailable:'Sync unavailable',reauth:'Sign in to resume syncing',invalid:'Changes need attention',conflict:'Review changes'}[cloud.status]||'Saved on this device';}
function authControls(){return `<span class="sync-label" role="status">${esc(syncLabel())}</span><button class="button small ${cloud?.user?'':'primary'}" id="cloud-auth">${cloud?.user?esc(cloud.user.name||'Your account'):'Sign in & sync'}</button>`;}
function syncNotice(){
  if(!cloud)return '';
  if(cloud.conflict)return '<div class="sync-banner attention"><span>Another device changed the same kitchen items. Review both versions before syncing.</span><button class="button small" id="review-conflict">Review changes</button></div>';
  if(cloud.status==='reauth')return '<div class="sync-banner attention"><span>Your session expired. Changes are saved here until you sign in again.</span><button class="button small" id="resume-signin">Sign in</button></div>';
  if(cloud.status==='invalid'||cloud.storageFailed)return '<div class="sync-banner attention"><span>We could not save all your changes. Download a backup to keep a copy.</span><button class="button small" id="save-sync-backup">Download backup</button></div>';
  if(cloud.status==='offline')return '<div class="sync-banner"><span>Cloud sync is unavailable. Your changes are saved on this device and will retry when connected.</span><button class="button small" id="retry-sync">Retry</button></div>';
  if(cloud.status==='setup')return '<div class="sync-banner"><span>Your local kitchen is ready. Sync between devices will be available once cloud setup is complete.</span></div>';
  if(cloud.status==='unavailable')return '<div class="sync-banner"><span>Account services could not be reached. Your local kitchen is still available.</span><button class="button small" id="retry-sync">Retry</button></div>';
  return '';
}
function bindSyncControls(){on('cloud-auth',()=>cloud?.user?settings():location.assign('/login'));on('review-conflict',reviewConflict);on('resume-signin',()=>authForm());on('save-sync-backup',()=>downloadKitchen(state));on('retry-sync',()=>cloud.user?cloud.sync():cloud.start());}
function paintSyncUI(){if($('#sync-controls'))$('#sync-controls').innerHTML=authControls();if($('#sync-notice'))$('#sync-notice').innerHTML=syncNotice();if($('#profile-status'))$('#profile-status').textContent=syncLabel();bindSyncControls();}
function downloadKitchen(data,filename='pantry-table-backup.json'){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reviewConflict(){if(!cloud.conflict)return;modal('Choose which kitchen to keep',`<p>These items changed on both devices:</p><ul class="conflict-list">${cloud.conflict.conflicts.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>Changes are paused. Choosing a version replaces the whole kitchen with that version. Download both backups before choosing if you want to keep a copy.</p><div class="settings-actions"><button class="button" id="backup-here">Download this device</button><button class="button" id="backup-there">Download cloud version</button></div><div class="form-actions"><button class="button" id="use-cloud">Keep cloud kitchen</button><button class="button primary" id="use-local">Keep this device’s kitchen</button></div>`);on('backup-here',()=>downloadKitchen(cloud.local,'pantry-table-this-device.json'));on('backup-there',()=>downloadKitchen(cloud.conflict.remote.state,'pantry-table-cloud.json'));on('use-cloud',()=>{$('#modal').close();cloud.resolveConflict('cloud');});on('use-local',()=>{$('#modal').close();cloud.resolveConflict('local');});}
async function logout(){try{await cloud.signOut();$('#modal').close();toast('Signed out. This device’s guest kitchen is open.');}catch(e){toast(e.message);}}
function authForm(signup=false){
  if(!cloud.configured){modal('Your kitchen, on every device',`<p>Sign-in and cloud sync are being prepared. For now, your kitchen is saved in this browser.</p><p>Once setup is complete, sign in with the same account on your iPad and iPhone to keep them together.</p><button class="button" id="check-accounts">Check again</button>`);on('check-accounts',async()=>{$('#modal').close();await cloud.start();if(cloud.configured)authForm();});return;}
  modal(signup?'Make yourself at home':'Welcome back',`<p>One account for your pantry, meals, recipes, and kitchen memories.</p><form id="account-form">${signup?field('Your name','<input name="name" autocomplete="name" maxlength="100" required>'):''}${field('Email','<input name="email" type="email" autocomplete="email" required maxlength="254">')}${field('Password',`<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?'12':'1'}" maxlength="128" required>`)}${signup?'<p class="help-text">Use at least 12 characters. Your existing guest kitchen stays on this device until you choose to import it.</p>':''}<p id="account-error" class="form-error" role="alert"></p>${actions(signup?'Create account':'Sign in')}</form><div class="auth-links"><button class="text-button" id="switch-auth">${signup?'Already have an account? Sign in':'New here? Create an account'}</button>${!signup&&cloud.recovery?'<button class="text-button" id="forgot-password">Forgot password?</button>':''}</div>`);
  on('switch-auth',()=>authForm(!signup));on('forgot-password',forgotPasswordForm);
  $('#account-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]');button.disabled=true;$('#account-error').textContent='';try{const values=Object.fromEntries(new FormData(form));values.email=values.email.trim();const response=await cloud.request('/api/auth/'+(signup?'sign-up/email':'sign-in/email'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});if(!response.ok){$('#account-error').textContent=response.status===429?'Too many attempts. Wait a minute and try again.':response.status>=500?'Accounts could not connect. Please try again shortly.':signup?'Could not create an account. Check your details, or try signing in.':'The email or password did not match. Please try again.';return;}$('#modal').close();await cloud.start();toast('Your account kitchen is open.');}catch{if($('#account-error'))$('#account-error').textContent='Could not connect. Please check your internet connection.';}finally{button.disabled=false;}};
}
function forgotPasswordForm(){modal('A fresh start',`<form id="forgot-form">${field('Your account email','<input name="email" type="email" autocomplete="email" required>')}<p id="recovery-message" role="status"></p>${actions('Send reset link')}</form>`);$('#forgot-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{const email=new FormData(e.target).get('email');await cloud.request('/api/auth/request-password-reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,redirectTo:location.origin+'/?reset-password=1'})});$('#recovery-message').textContent='If an account matches, you will receive a password reset email.';}catch{$('#recovery-message').textContent='Could not connect. Please try again.';}finally{button.disabled=false;}};}
function resetPasswordForm(){const token=new URL(location.href).searchParams.get('token');modal('Choose a new password',`<form id="reset-form">${field('New password','<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required>')}<p id="reset-message" role="alert">${token?'':'This reset link is incomplete. Request a new link.'}</p>${actions('Save new password')}</form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{const response=await cloud.request('/api/auth/reset-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,newPassword:new FormData(e.target).get('password')})});if(!response.ok){$('#reset-message').textContent='This link may have expired. Request a new password reset link.';return;}history.replaceState(null,'',location.pathname);$('#modal').close();toast('Password updated. You can now sign in.');}catch{$('#reset-message').textContent='Could not connect. Please try again.';}finally{button.disabled=false;}};}
